"use client"

import { useState } from "react"

import "./tybow-collection.css"

import { cn } from "@/lib/utils"

export type HomeCardPhoto = {
  src?: string
  alt: string
  label?: string
  fit?: "cover" | "contain"
}

export type HomeCardProps = {
  title: string
  href?: string
  price?: string
  sqft?: number | string
  beds?: string
  baths?: string
  garage?: string
  kind?: string
  modelHome?: boolean
  photos: HomeCardPhoto[]
  compared?: boolean
  onCompare?: () => void
  compareFull?: boolean
  className?: string
}

function fmtSqft(value?: number | string) {
  if (value == null || value === "") return ""
  const n = typeof value === "number" ? value : Number(String(value).replace(/[^\d.]/g, ""))
  if (!Number.isFinite(n)) return String(value)
  return n.toLocaleString("en-CA")
}

export function HomeCard({
  title,
  href,
  price,
  sqft,
  beds,
  baths,
  garage,
  kind,
  modelHome,
  photos,
  compared,
  onCompare,
  compareFull,
  className,
}: HomeCardProps) {
  const [on, setOn] = useState(0)
  const slides = photos.length ? photos : [{ alt: title, label: "Exterior" }]
  const current = slides[on]
  const sqftLabel = fmtSqft(sqft)
  const specs = [kind, beds && `${beds} Bed`, baths && `${baths} Bath`, garage, sqftLabel && `${sqftLabel} Sq Ft`]
    .filter(Boolean)
    .join(" · ")

  function go(next: number) {
    if (slides.length < 2) return
    setOn((next + slides.length) % slides.length)
  }

  return (
    <article
      className={cn(
        "tybow-home-card group relative flex cursor-pointer flex-col overflow-hidden border border-border bg-card transition-[background-color,border-color,transform] duration-200 ease-out hover:-translate-y-0.5 hover:border-primary/40 hover:bg-muted",
        compareFull && "is-full",
        className,
      )}
      onClick={(event) => {
        if (!href) return
        if ((event.target as HTMLElement).closest("a, button, label, input")) return
        window.location.href = href
      }}
    >
      <div className="relative aspect-[3/2] overflow-hidden bg-muted">
        {slides.map((slide, index) =>
          slide.src ? (
            // eslint-disable-next-line @next/next/no-img-element
            <img
              key={`${slide.src}-${index}`}
              src={slide.src}
              alt={index === on ? `${title} — ${slide.label ?? slide.alt}` : ""}
              className={cn(
                "tybow-home-card-slide absolute inset-0 size-full transition-opacity duration-300",
                index === on ? "opacity-100" : "opacity-0",
                slide.fit === "contain" ? "object-contain bg-background p-2.5" : "object-cover",
              )}
            />
          ) : (
            <div
              key={`${slide.alt}-${index}`}
              className={cn(
                "tybow-home-card-slide absolute inset-0 bg-muted transition-opacity duration-300",
                index === on ? "opacity-100" : "opacity-0",
              )}
              role="img"
              aria-label={slide.alt}
            />
          ),
        )}

        {slides.length > 1 ? (
          <>
            <button
              type="button"
              aria-label={`Previous image of ${title}`}
              className="tybow-home-card-arrow absolute top-1/2 left-2.5 z-[3] grid size-[34px] -translate-y-1/2 place-items-center rounded-full border border-primary-foreground/40 bg-foreground/70 text-xl text-primary-foreground transition-opacity"
              onClick={(event) => {
                event.preventDefault()
                event.stopPropagation()
                go(on - 1)
              }}
            >
              ‹
            </button>
            <button
              type="button"
              aria-label={`Next image of ${title}`}
              className="tybow-home-card-arrow absolute top-1/2 right-2.5 z-[3] grid size-[34px] -translate-y-1/2 place-items-center rounded-full border border-primary-foreground/40 bg-foreground/70 text-xl text-primary-foreground transition-opacity"
              onClick={(event) => {
                event.preventDefault()
                event.stopPropagation()
                go(on + 1)
              }}
            >
              ›
            </button>
            <div className="absolute bottom-2.5 left-1/2 z-[3] flex -translate-x-1/2 gap-1.5" aria-hidden>
              {slides.map((slide, index) => (
                <span
                  key={`${slide.alt}-${index}`}
                  className={cn(
                    "size-2 rounded-full border border-primary-foreground/70",
                    index === on && "border-primary bg-primary",
                  )}
                />
              ))}
            </div>
          </>
        ) : null}

        {current?.label ? (
          <span className="absolute bottom-2.5 left-2.5 z-[2] bg-foreground/70 px-2 py-0.5 text-[0.62rem] tracking-[0.1em] text-primary-foreground uppercase">
            {current.label}
          </span>
        ) : null}

        {modelHome ? (
          <span className="absolute top-2.5 left-2.5 z-[3] bg-primary/90 px-2.5 py-1 text-[0.62rem] font-semibold tracking-[0.12em] text-primary-foreground uppercase">
            Model home
          </span>
        ) : null}

        {sqftLabel ? (
          <span
            className={cn(
              "absolute left-2.5 z-[2] border border-primary-foreground/30 bg-primary/90 px-2.5 py-1 text-[0.62rem] font-semibold tracking-[0.12em] text-primary-foreground uppercase",
              modelHome ? "top-11" : "top-2.5",
            )}
          >
            {sqftLabel} sq ft
          </span>
        ) : null}

        {onCompare ? (
          <label
            className="tybow-home-card-compare absolute top-2.5 right-2.5 z-[3] flex cursor-pointer items-center gap-2 border border-primary-foreground/35 bg-primary/90 px-3 py-1.5 text-[0.62rem] font-semibold tracking-[0.14em] text-primary-foreground uppercase"
            title="Add to compare"
            onClick={(event) => event.stopPropagation()}
          >
            <input
              type="checkbox"
              className="sr-only"
              checked={compared}
              aria-label={`Compare ${title}`}
              onChange={onCompare}
            />
            <span className="tybow-home-card-check-box relative size-3.5 shrink-0 border-[1.5px] border-primary-foreground/70" />
            Compare
          </label>
        ) : null}
      </div>

      <div className="px-[18px] pt-4 pb-[18px]">
        <h3 className="font-display text-[length:clamp(1.35rem,2vw,1.65rem)] font-medium tracking-[-0.01em] text-foreground">
          {href ? (
            <a href={href} className="text-inherit no-underline hover:text-primary">
              {title}
            </a>
          ) : (
            title
          )}
        </h3>
        {price ? (
          <p className="mt-1.5 font-sans text-[1.0625rem] tracking-[0.04em] text-primary">
            {price}
          </p>
        ) : null}
        {specs ? (
          <p className="mt-2 text-[0.8125rem] text-muted-foreground">{specs}</p>
        ) : null}
        <span className="tybow-home-card-cta mt-2.5 inline-block text-[0.68rem] tracking-[0.12em] text-primary uppercase transition">
          View home details →
        </span>
      </div>
    </article>
  )
}

import type { ComponentProps, ReactNode } from "react"

import { cn } from "@/lib/utils"

function ArrowIcon() {
  return (
    <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden>
      <path
        d="M3 8h10M9 4l4 4-4 4"
        stroke="currentColor"
        strokeWidth="1.4"
        strokeLinecap="square"
      />
    </svg>
  )
}

export type ArrowButtonProps = {
  variant?: "cream" | "inverse" | "ghost"
  href?: string
  className?: string
  children: ReactNode
} & Omit<ComponentProps<"button">, "className">

export function ArrowButton({
  variant = "cream",
  href,
  className,
  children,
  type = "button",
  ...props
}: ArrowButtonProps) {
  const classes = cn(
    "inline-flex min-h-[3.25rem] items-center gap-3 pr-1.5 pl-5 font-sans text-[0.92rem] font-semibold tracking-[0.04em] uppercase",
    variant === "cream" &&
      "bg-primary-foreground text-foreground shadow-[0_10px_28px_color-mix(in_oklch,var(--foreground)_32%,transparent)] hover:bg-white",
    variant === "inverse" && "bg-primary text-primary-foreground hover:brightness-90",
    variant === "ghost" &&
      "min-h-[3.25rem] border-[1.5px] border-primary-foreground bg-foreground/60 px-5 text-primary-foreground hover:border-white hover:bg-foreground/80",
    className,
  )

  const iconWrap =
    variant === "ghost" ? null : (
      <span
        className={cn(
          "grid size-9 place-items-center",
          variant === "cream" && "bg-primary text-primary-foreground",
          variant === "inverse" && "bg-primary-foreground text-primary",
        )}
      >
        <ArrowIcon />
      </span>
    )

  const inner = (
    <>
      {children}
      {iconWrap}
    </>
  )

  if (href) {
    return (
      <a href={href} className={classes}>
        {inner}
      </a>
    )
  }

  return (
    <button type={type} className={classes} {...props}>
      {inner}
    </button>
  )
}

import { cn } from "@/lib/utils"

export type FlushPhotoProps = {
  src?: string
  alt: string
  label?: string
  fit?: "cover" | "contain"
  className?: string
}

export type MediaFrame = { src?: string; alt: string }

export function MediaStack({
  frames,
  on,
  slideClassName,
  className,
  objectPosition,
}: {
  frames: MediaFrame[]
  on: number
  slideClassName: string
  className?: string
  objectPosition?: string
}) {
  return (
    <div className={cn("relative overflow-hidden bg-muted", className)}>
      {frames.map((frame, index) =>
        frame.src ? (
          // Parent owns crop. Animation classes must land on the img.
          // eslint-disable-next-line @next/next/no-img-element
          <img
            key={`${frame.src}-${index}`}
            src={frame.src}
            alt={index === on ? frame.alt : ""}
            decoding="async"
            className={cn(slideClassName, index === on && "is-on")}
            style={objectPosition ? { objectPosition } : undefined}
          />
        ) : (
          <div
            key={`${frame.alt}-${index}`}
            className={cn(
              slideClassName,
              index === on && "is-on",
              "flex items-center justify-center bg-muted",
            )}
            role="img"
            aria-label={frame.alt}
          />
        ),
      )}
    </div>
  )
}

export function FlushPhoto({
  src,
  alt,
  label = "replace with client photo",
  fit = "cover",
  className,
}: FlushPhotoProps) {
  return (
    <div className={cn("relative overflow-hidden bg-muted", className)}>
      {src ? (
        // Parent owns crop and radius. No inner mat.
        // eslint-disable-next-line @next/next/no-img-element
        <img
          src={src}
          alt={alt}
          className={cn(
            "absolute inset-0 size-full",
            fit === "contain" ? "object-contain" : "object-cover",
          )}
        />
      ) : (
        <div
          className="absolute inset-0 flex items-center justify-center bg-muted px-6 text-center"
          role="img"
          aria-label={alt}
        >
          <p className="text-sm text-muted-foreground">{label}</p>
        </div>
      )}
    </div>
  )
}

/* Motion ported from The Pines: wh-pines.css + wh-pe-brand.css.
   Token-only. Values (timings, easings, travel) stay literal. */

@keyframes tybow-pull {
  to {
    transform: none;
    opacity: 1;
  }
}

.tybow-pull {
  display: inline-block;
  transform: translateY(0.42em);
  opacity: 0;
  animation: tybow-pull 0.72s cubic-bezier(0.16, 1, 0.3, 1) forwards;
  animation-delay: calc(var(--i, 0) * 90ms + 80ms);
}

.tybow-pull-late {
  transform: translateY(0.8rem);
  opacity: 0;
  animation: tybow-pull 0.8s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

/* Ken Burns lives on the IMG, not a wrapper. */
.tybow-hero-slide {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  max-width: none;
  object-fit: cover;
  object-position: 50% 52%;
  opacity: 0;
  transform: scale(1.02);
  transition:
    opacity 1.1s cubic-bezier(0.22, 1, 0.36, 1),
    transform 7s cubic-bezier(0.22, 1, 0.36, 1);
  will-change: opacity, transform;
}

.tybow-hero-slide.is-on {
  opacity: 1;
  transform: scale(1);
}

.tybow-look-slide {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  max-width: none;
  object-fit: cover;
  opacity: 0;
  transition: opacity 0.4s cubic-bezier(0.22, 1, 0.36, 1);
}

.tybow-look-slide.is-on {
  opacity: 1;
}

.tybow-overview-slide {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  max-width: none;
  object-fit: cover;
  opacity: 0;
  transition: opacity 0.55s cubic-bezier(0.22, 1, 0.36, 1);
}

.tybow-overview-slide.is-on {
  opacity: 1;
  z-index: 1;
}

.tybow-gallery {
  display: flex;
  flex-direction: row;
  gap: 1px;
  width: 100%;
  height: min(56vh, 32rem);
  min-height: 22rem;
  overflow: hidden;
  background: var(--foreground);
}

.tybow-gallery-item {
  position: relative;
  overflow: hidden;
  flex: 0.5 1 2.55rem;
  min-width: 2.45rem;
  height: 100%;
  padding: 0;
  border: 0;
  background: var(--foreground);
  cursor: pointer;
  text-align: left;
  line-height: 0;
  transition: flex-grow 0.5s cubic-bezier(0.22, 1, 0.36, 1);
}

.tybow-gallery-item.is-active {
  flex-grow: 16;
}

.tybow-gallery-item img,
.tybow-gallery-item .tybow-gallery-frame {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 50% 48%;
}

.tybow-gallery-item::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(
    to right,
    color-mix(in oklch, var(--foreground) 88%, transparent) 0%,
    color-mix(in oklch, var(--foreground) 62%, transparent) 55%,
    color-mix(in oklch, var(--foreground) 28%, transparent) 100%
  );
  opacity: 1;
  transition: opacity 0.3s ease;
}

.tybow-gallery-item.is-active::after {
  opacity: 0;
}

.tybow-gallery-spine {
  position: absolute;
  inset: 0 auto 0 0;
  z-index: 1;
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  padding: 1.05rem 0.55rem;
  font-size: 0.8rem;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--primary-foreground);
  text-shadow: 0 1px 12px color-mix(in oklch, var(--foreground) 70%, transparent);
  pointer-events: none;
  opacity: 1;
  transition: opacity 0.25s ease;
}

.tybow-gallery-item.is-active .tybow-gallery-spine {
  opacity: 0;
}

.tybow-gallery-cap {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 1;
  padding: 2.6rem 1.2rem 1.05rem;
  background: linear-gradient(
    to top,
    color-mix(in oklch, var(--foreground) 70%, transparent),
    transparent
  );
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--primary-foreground);
  pointer-events: none;
  opacity: 0;
  transform: translateY(0.5rem);
  transition:
    opacity 0.3s ease,
    transform 0.3s ease;
}

.tybow-gallery-item.is-active .tybow-gallery-cap {
  opacity: 1;
  transform: none;
}

.tybow-deck-card-body,
.tybow-deck-card::after {
  transition:
    opacity 420ms ease,
    transform 420ms ease;
}

.tybow-deck-track .tybow-deck-card:not(.is-active) .tybow-deck-card-body {
  opacity: 0.55;
  transform: translateY(10px);
}

.tybow-spec-line {
  --pin-line-delay: 0ms;
}

.tybow-spec-line::after {
  content: "";
  position: absolute;
  inset: auto 0 0 0;
  height: 1px;
  background: var(--border);
}

@media (prefers-reduced-motion: no-preference) {
  .tybow-spec .tybow-spec-line::after {
    transform: scaleX(0);
    transform-origin: left center;
    transition: transform 620ms cubic-bezier(0.23, 1, 0.32, 1)
      var(--pin-line-delay, 0ms);
  }

  .tybow-spec .tybow-spec-tick {
    opacity: 0;
    transform: translateX(-5px);
    transition:
      opacity 420ms cubic-bezier(0.23, 1, 0.32, 1) var(--pin-line-delay, 0ms),
      transform 420ms cubic-bezier(0.23, 1, 0.32, 1) var(--pin-line-delay, 0ms);
  }

  .tybow-spec.is-inview .tybow-spec-line::after {
    transform: scaleX(1);
  }

  .tybow-spec.is-inview .tybow-spec-tick {
    opacity: 1;
    transform: none;
  }

  .tybow-spec-line:nth-child(1) {
    --pin-line-delay: 300ms;
  }
  .tybow-spec-line:nth-child(2) {
    --pin-line-delay: 375ms;
  }
  .tybow-spec-line:nth-child(3) {
    --pin-line-delay: 450ms;
  }
  .tybow-spec-line:nth-child(4) {
    --pin-line-delay: 525ms;
  }
  .tybow-spec-line:nth-child(5) {
    --pin-line-delay: 600ms;
  }
  .tybow-spec-line:nth-child(6) {
    --pin-line-delay: 675ms;
  }
}

@media (max-width: 800px) {
  .tybow-gallery {
    height: auto;
    min-height: 0;
    flex-direction: column;
  }

  .tybow-gallery-item {
    flex: 0 0 2.65rem;
    width: 100%;
    min-width: 0;
    height: 2.65rem;
    transition:
      height 0.4s cubic-bezier(0.22, 1, 0.36, 1),
      flex-basis 0.4s cubic-bezier(0.22, 1, 0.36, 1);
  }

  .tybow-gallery-item.is-active {
    flex: 0 0 22rem;
    height: 22rem;
  }

  .tybow-gallery-item::after {
    background: linear-gradient(
      to top,
      color-mix(in oklch, var(--foreground) 88%, transparent) 0%,
      color-mix(in oklch, var(--foreground) 45%, transparent) 70%,
      transparent 100%
    );
  }

  .tybow-gallery-spine {
    writing-mode: horizontal-tb;
    transform: none;
    inset: auto auto 0.7rem 0.9rem;
    padding: 0;
    font-size: 0.78rem;
    letter-spacing: 0.16em;
  }
}

@media (max-width: 959px) {
  .tybow-deck-track .tybow-deck-card:not(.is-active) .tybow-deck-card-body {
    opacity: 1;
    transform: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .tybow-pull,
  .tybow-pull-late {
    animation: none;
    opacity: 1;
    transform: none;
  }

  .tybow-hero-slide,
  .tybow-hero-slide.is-on,
  .tybow-look-slide,
  .tybow-overview-slide,
  .tybow-gallery-item,
  .tybow-gallery-item::after,
  .tybow-gallery-spine,
  .tybow-gallery-cap,
  .tybow-deck-card-body,
  .tybow-deck-card::after {
    transition: none;
    transform: none;
  }

  .tybow-deck-track .tybow-deck-card:not(.is-active) .tybow-deck-card-body {
    opacity: 1;
    transform: none;
  }
}
